        Mentor member = new Mentor(name, sessions, slots);
        lines.add(member.line());
        total += member.credits();
    }
    public List<String> lines() { return List.copyOf(lines); }
    public long totalCredits() { return total; }
}

package roster;
/** A read-only text capability shared by otherwise unrelated objects. */
public interface LineSource {
    String line();
}

package roster;
import java.util.Objects;

/** Shared member data and validation; subclasses supply their genuine variation. */
public abstract class Member implements LineSource {
    private final String name;
    private final int sessions;
    protected Member(String name, int sessions) {
        Objects.requireNonNull(name, "name");
        if (name.isBlank()) throw new IllegalArgumentException("name");
        if (sessions < 0 || sessions > 40) throw new IllegalArgumentException("sessions");
        this.name = name;
        this.sessions = sessions;
    }
    public final String name() { return name; }
    public final int sessions() { return sessions; }
    protected final int sessionCredits() { return sessions * 2; }
    protected abstract String role();
    public abstract int credits();
    public final String line() { return name + " | " + role() + " | " + credits(); }
}

package roster;
public final class Mentor extends Member {
    private final int mentoringSlots;
    public Mentor(String name, int sessions, int mentoringSlots) {
        super(name, sessions);
        if (mentoringSlots < 0 || mentoringSlots > 8) throw new IllegalArgumentException("mentoringSlots");
        this.mentoringSlots = mentoringSlots;
    }
    protected String role() { return "mentor"; }
    public int credits() { return sessionCredits() + mentoringSlots * 3; }
}

